create table if not exists public.cash_register_transactions(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,register_id bigint not null references public.cash_registers(id) on delete cascade,type text not null,amount numeric(14,2) not null,reference_type text,reference_id bigint,notes text,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
alter table public.cash_register_transactions enable row level security; revoke all on public.cash_register_transactions from anon,authenticated; grant select,insert,update,delete on public.cash_register_transactions to authenticated;
create policy cash_register_transactions_tenant on public.cash_register_transactions for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_cash_register_transaction_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from cash_registers r where r.id=new.register_id and r.business_id=new.business_id) then raise exception 'register does not belong to business'; end if; if new.amount<=0 then raise exception 'amount must be positive'; end if; return new; end$$;
revoke all on function private.enforce_cash_register_transaction_business() from public,anon,authenticated;
create trigger trg_cash_register_transaction_business before insert or update on public.cash_register_transactions for each row execute function private.enforce_cash_register_transaction_business();